INSERT INTO senses (id, word_id, sense_no, pos, definition, example) OVERRIDING SYSTEM VALUE VALUES
  (1, 1, 1, 'v', 'to humiliate, degrade', 'After being overthrown and abased, the deposed leader offered to bow down to his conqueror.'),
  (2, 2, 1, 'v', 'to reduce, lessen', 'The rain poured down for a while, then abated.'),
  (3, 3, 1, 'v', 'to give up a position, usually one of leadership', 'When he realized that the revolutionaries would surely win, the king abdicated his throne.'),
  (4, 4, 1, 'v', 'to kidnap, take by force', 'The evildoers abducted the fairy princess from her happy home.'),
  (5, 5, 1, 'n', 'something that differs from the norm', 'In 1918, the Boston Red Sox won the World Series, but the success turned out to be an aberration, and the Red Sox have not won a World Series since.'),
  (6, 6, 1, 'v', 'to aid, help, encourage', 'The spy succeeded only because he had a friend on the inside to abet him.'),
  (7, 7, 1, 'v', 'to hate, detest', 'Because he always wound up kicking himself in the head when he tried to play soccer, Oswald began to abhor the sport.'),
  (8, 8, 1, 'v', 'to put up with', 'Though he did not agree with the decision, Chuck decided to abide by it.'),
  (9, 8, 2, 'v', 'to remain', 'Despite the beating they''ve taken from the weather throughout the millennia, the mountains abide.'),
  (10, 9, 1, 'adj', 'wretched, pitiful', 'After losing all her money, falling into a puddle, and breaking her ankle, Eloise was abject.'),
  (11, 10, 1, 'v', 'to reject, renounce', 'To prove his honesty, the President abjured the evil policies of his wicked predecessor.'),
  (12, 11, 1, 'n', 'denial of comfort to oneself', 'The holy man slept on the floor, took only cold showers, and generally followed other practices of abnegation.'),
  (13, 12, 1, 'v', 'to give up on a half-finished project or effort', 'After they ran out of food, the men, attempting to jump rope around the world, had to abort and go home.'),
  (14, 13, 1, 'v', 'to cut down, shorten', 'The publisher thought the dictionary was too long and abridged it.'),
  (15, 13, 2, 'adj', 'shortened', 'Moby-Dick is such a long book that even the abridged version is longer than most normal books.'),
  (16, 14, 1, 'v', 'to abolish, usually by authority', 'The Bill of Rights assures that the government cannot abrogate our right to a free press.'),
  (17, 15, 1, 'v', 'to sneak away and hide', 'In the confusion, the super-spy absconded into the night with the secret plans.'),
  (18, 16, 1, 'n', 'freedom from blame, guilt, sin', 'Once all the facts were known, the jury gave Angela absolution by giving a verdict of not guilty.'),
  (19, 17, 1, 'v', 'to freely choose not to commit an action', 'Everyone demanded that Angus put on the kilt, but he did not want to do it and abstained.'),
  (20, 18, 1, 'adj', 'hard to comprehend', 'Everyone else in the class understood geometry easily, but John found the subject abstruse.'),
  (21, 19, 1, 'v', 'to agree', 'When the class asked the teacher whether they could play baseball instead of learn grammar they expected him to refuse, but instead he acceded to their request.'),
  (22, 20, 1, 'v', 'to stress, highlight', 'Psychologists agree that those people who are happiest accentuate the positive in life.'),
  (23, 21, 1, 'adj', 'obtainable, reachable', 'After studying with SparkNotes and getting a great score on the SAT, Marlena happily realized that her goal of getting into an Ivy-League college was accessible.'),
  (24, 22, 1, 'n', 'high praise', 'Greg''s excellent poem won the acclaim of his friends.'),
  (25, 23, 1, 'n', 'high praise, special distinction', 'Everyone offered accolades to Sam after he won the Noble Prize.'),
  (26, 24, 1, 'adj', 'helpful, obliging, polite', 'Though the apartment was not big enough for three people, Arnold, Mark, and Zebulon were all friends and were accommodating to each other.'),
  (27, 25, 1, 'n', 'an agreement', 'After much negotiating, England and Iceland finally came to a mutually beneficial accord about fishing rights off the cost of Greenland.'),
  (28, 26, 1, 'v', 'to confront verbally', 'Though Antoinette was normally quite calm, when the waiter spilled soup on her for the fourth time in 15 minutes she stood up and accosted the man.'),
  (29, 27, 1, 'n', 'slow growth in size or amount', 'Stalactites are formed by the accretion of minerals from the roofs of caves.'),
  (30, 28, 1, 'adj', 'biting, bitter in tone or taste', 'Jill became extremely acerbic and began to cruelly make fun of all her friends.'),
  (31, 29, 1, 'v', 'to agree without protesting', 'Though Mr. Correlli wanted to stay outside and work in his garage, when his wife told him that he had better come in to dinner, he acquiesced to her demands.'),
  (32, 30, 1, 'n', 'bitterness, discord', 'Though they vowed that no girl would ever come between them, Biff and Trevor could not keep acrimony from overwhelming their friendship after they both fell in love with the lovely Teresa.'),
  (33, 31, 1, 'n', 'keen insight', 'Because of his mathematical acumen, Larry was able to figure out in minutes problems that took other students hours.'),
  (34, 32, 1, 'adj', 'sharp, severe', 'Arnold could not walk because the pain in his foot was so acute.'),
  (35, 32, 2, 'adj', 'having keen insight', 'Because she was so acute, Libby instantly figured out how the magician pulled off his "magic."'),
  (36, 33, 1, 'adj', 'impervious, immovable, unyielding', 'Though public pressure was intense, the President remained adamant about his proposal.'),
  (37, 34, 1, 'adj', 'extremely skilled', 'Tarzan was adept at jumping from tree to tree like a monkey.'),
  (38, 35, 1, 'n', 'to stick to something', 'We adhered the poster to the wall with tape.'),
  (39, 35, 2, 'n', 'to follow devoutly', 'He adhered to the dictates of his religion without question.'),
  (40, 36, 1, 'v', 'to caution, criticize, reprove', 'Joe''s mother admonished him not to ruin his appetite by eating cookies before dinner.'),
  (41, 37, 1, 'v', 'to decorate', 'We adorned the tree with ornaments.'),
  (42, 38, 1, 'adj', 'skillful, dexterous', 'The adroit thief could pick someone''s pocket without attracting notice.'),
  (43, 39, 1, 'n', 'extreme praise', 'Though the book was pretty good, Marcy did not believe it deserved the adulation it received.'),
  (44, 40, 1, 'v', 'to sketch out in a vague way', 'The coach adumbrated a game plan, but none of the players knew precisely what to do.'),
  (45, 41, 1, 'adj', 'antagonistic, unfavorable, dangerous', 'Because of adverse conditions, the hikers decided to give up trying to climb the mountain.'),
  (46, 42, 1, 'v', 'to argue in favor of something', 'Arnold advocated turning left at the stop sign, even though everyone else thought we should turn right.'),
  (47, 42, 2, 'n', 'a person who argues in favor of something', 'In addition to wanting to turn left at every stop sign, Arnold was also a great advocate of increasing national defense spending.'),
  (48, 43, 1, 'adj', 'somehow related to the air', 'We watched as the fighter planes conducted aerial maneuvers.'),
  (49, 44, 1, 'adj', 'artistic, related to the appreciation of beauty', 'We hired Susan as our interior decorator because she has such a fine aesthetic sense.'),
  (50, 45, 1, 'adj', 'friendly, amiable', 'People like to be around George because he is so affable and good-natured.'),
  (51, 46, 1, 'n', 'a spontaneous feeling of closeness', 'Jerry didn''t know why, but he felt an incredible affinity for Kramer the first time they met.'),
  (52, 47, 1, 'adj', 'rich, wealthy', 'Mrs. Grebelski was affluent, owning a huge house, three cars, and an island near Maine.'),
  (53, 48, 1, 'n', 'an insult', 'Bernardo was very touchy, and took any slight as an affront to his honor.'),
  (54, 49, 1, 'v', 'to increase or make greater', 'Joseph always dropped the names of the famous people his father knew as a way to aggrandize his personal stature.'),
  (55, 50, 1, 'n', 'a whole or total', 'The three branches of the U.S. Government form an aggregate much more powerful than its individual parts.'),
  (56, 50, 2, 'v', 'to gather into a mass', 'The dictator tried to aggregate as many people into his army as he possibly could.'),
  (57, 51, 1, 'adj', 'distressed, wronged, injured', 'The foreman mercilessly overworked his aggrieved employees.'),
  (58, 52, 1, 'adj', 'quick, nimble', 'The dogs were too slow to catch the agile rabbit.'),
  (59, 53, 1, 'adj', 'believing that the existence of God cannot be proven or disproven', 'Joey''s parents are very religious, but he is agnostic.'),
  (60, 54, 1, 'n', 'farming', 'It was a huge step in the progress of civilization when tribes left hunting and gathering and began to develop more sustainable methods of obtaining food, such as agriculture.'),
  (61, 55, 1, 'n', 'a passageway between rows of seats', 'Once we got inside the stadium we walked down the aisle to our seats.'),
  (62, 56, 1, 'n', 'eagerness, speed', 'For some reason, Chuck loved to help his mother whenever he could, so when his mother asked him to set the table he did so with alacrity.'),
  (63, 57, 1, 'n', 'a false name or identity', 'He snuck past the guards by using an alias and fake ID.'),
  (64, 58, 1, 'v', 'to soothe, ease', 'The chairman of the Federal Reserve gave a speech to try to allay investors'' fears about an economic downturn.'),
  (65, 59, 1, 'v', 'to assert, usually without proof', 'The policeman had alleged that Marshall committed the crime, but after the investigation turned up no evidence, Marshall was set free.'),
  (66, 60, 1, 'v', 'to relieve, make more bearable', 'This drug will alleviate the symptoms of the terrible disease, but only for a while.'),
  (67, 61, 1, 'v', 'to distribute, set aside', 'The Mayor allocated 30 percent of the funds for improving the town''s schools.'),
  (68, 62, 1, 'adj', 'reserved, distant', 'The scientist could sometimes seem aloof, as if he didn''t care about his friends or family, but really he was just thinking about quantum mechanics.'),
  (69, 63, 1, 'n', 'a dispute, fight', 'Jason and Lionel blamed one another for the car accident, leading to an altercation.'),
  (70, 64, 1, 'v', 'to bring together, unite', 'Because of his great charisma, the presidential candidate was able to amalgamate all democrats and republicans under his banner.'),
  (71, 65, 1, 'adj', 'uncertain, variably interpretable', 'Some people think Caesar married Cleopatra for her power, others believe he was charmed by her beauty. His actual reasons are ambiguous.'),
  (72, 66, 1, 'adj', 'having opposing feelings', 'My feelings about Calvin are ambivalent because on one hand he is a loyal friend, but on the other, he is a cruel and vicious thief.'),
  (73, 67, 1, 'v', 'to improve', 'The tense situation was ameliorated when Sam proposed a solution everyone could agree upon.'),
  (74, 68, 1, 'adj', 'willing, compliant', 'Our father was amenable when we asked him to drive us to the farm so we could go apple picking.'),
  (75, 69, 1, 'n', 'an item that increases comfort', 'Bill Gates''s house is stocked with so many amenities, he never has to do anything for himself.'),
  (76, 70, 1, 'adj', 'friendly', 'An amiable fellow, Harry got along with just about everyone.'),
  (77, 71, 1, 'adj', 'friendly', 'Claudia and Jimmy got divorced, but amicably and without hard feelings.'),
  (78, 72, 1, 'adj', 'showing love, particularly sexual', 'Whenever Albert saw Mariah wear her slinky red dress, he began to feel quite amorous.'),
  (79, 73, 1, 'adj', 'without definite shape or type', 'The effort was doomed from the start, because the reasons behind it were so amorphous and hard to pin down.'),
  (80, 74, 1, 'adj', 'being out of correct chronological order', 'In this book you''re writing, you say that the Pyramids were built after the Titanic sank, which is anachronistic.'),
  (81, 75, 1, 'n', 'something that reduces pain', 'Put this analgesic on the wound so that the poor man at least feels a little better.'),
  (82, 76, 1, 'adj', 'similar to, so that an analogy can be drawn', 'Though they are unrelated genetically, the bone structure of whales and fish is quite analogous.'),
  (83, 77, 1, 'n', 'one who wants to eliminate all government', 'An anarchist, Carmine wanted to dissolve every government everywhere.'),
  (84, 78, 1, 'n', 'a cursed, detested person', 'I never want to see that murderer. He is an anathema to me.'),
  (85, 79, 1, 'n', 'a short, humorous account', 'After dinner, Marlon told an anecdote about the time he got his nose stuck in a toaster.'),
  (86, 80, 1, 'n', 'loss of sensation', 'When the nerves in his spine were damaged, Mr. Hollins suffered anesthesia in his legs.'),
  (87, 81, 1, 'n', 'extreme sadness, torment', 'Angelos suffered terrible anguish when he learned that Buffy had died while combating a strange mystical force of evil.'),
  (88, 82, 1, 'adj', 'lively', 'When he begins to talk about drama, which is his true passion, he becomes very animated.'),
  (89, 83, 1, 'v', 'to incorporate territory or space', 'After defeating them in battle, the Russians annexed Poland.'),
  (90, 83, 2, 'n', 'a room attached to a larger room or space', 'He likes to do his studying in a little annex attached to the main reading room in the library.'),
  (91, 84, 1, 'v', 'to make void or invalid', 'After seeing its unforeseen and catastrophic effects, Congress sought to annul the law.'),
  (92, 85, 1, 'n', 'something that does not fit into the normal order ("That rip in the space- time continuum is certainly a spatial anomaly," said Spock to Captain Kirk.)', NULL),
  (93, 86, 1, 'adj', 'being unknown, unrecognized', 'Mary received a love poem from an anonymous admirer.'),
  (94, 87, 1, 'n', 'hostility', 'Superman and Bizarro Superman shared a mutual antagonism, and often fought.'),
  (95, 88, 1, 'n', 'something that came before', 'The great tradition of Western culture had its antecedent in the culture of Ancient Greece.'),
  (96, 89, 1, 'adj', 'ancient', 'The antediluvian man still believed that Eisenhower was president of the United States and that hot dogs cost a nickel.'),
  (97, 90, 1, 'n', 'a selected collection of writings, songs, etc.', 'The new anthology of Bob Dylan songs contains all his greatest hits and a few songs that you might never have heard before.'),
  (98, 91, 1, 'n', 'a strong dislike, repugnance', 'I know you love me, but because you are a liar and a thief, I feel nothing but antipathy for you.'),
  (99, 92, 1, 'adj', 'old, out of date', 'That antiquated car has none of the features, like power windows and steering, that make modern cars so great.'),
  (100, 93, 1, 'adj', 'clean, sterile', 'The antiseptic hospital was very bare, but its cleanliness helped to keep patients healthy.'),
  (101, 94, 1, 'n', 'the absolute opposite', 'Your values, which hold war and violence in the highest esteem, are the antithesis of my pacifist beliefs.'),
  (102, 95, 1, 'n', 'intense uneasiness', 'When he heard about the car crash, he felt anxiety because he knew that his girlfriend had been driving on the road where the accident occurred.'),
  (103, 96, 1, 'adj', 'lacking concern, emotion', 'Uninterested in politics, Bruno was apathetic about whether he lived under a capitalist or communist regime.'),
  (104, 97, 1, 'adj', 'fictitious, false, wrong', 'Because I am standing before you, it seems obvious that the stories circulating about my demise were apocryphal.'),
  (105, 98, 1, 'adj', 'inspiring shock, horror, disgust', 'The judge found the murderer''s crimes and lack of remorse appalling.'),
  (106, 99, 1, 'v', 'to calm, satisfy', 'When the child cries, the mother gives him candy to appease him.'),
  (107, 100, 1, 'v', 'to assess the worth or value of', 'A realtor will come over tonight to appraise our house.'),
  (108, 101, 1, 'v', 'to seize, arrest', 'The criminal was apprehended at the scene.'),
  (109, 101, 2, 'v', 'to perceive, understand, grasp', 'The student has trouble apprehending concepts in math and science.'),
  (110, 102, 1, 'n', 'praise', 'The crowd welcomed the heroes with approbation.'),
  (111, 103, 1, 'v', 'to take, make use of', 'The government appropriated the farmer''s land without justification.'),
  (112, 104, 1, 'adj', 'relating to water', 'The marine biologist studies starfish and other aquatic creatures.'),
  (113, 105, 1, 'adj', 'suitable for growing crops', 'The farmer purchased a plot of arable land on which he will grow corn and sprouts.'),
  (114, 106, 1, 'n', 'one who can resolve a dispute, make a decision', 'The divorce court judge will serve as the arbiter between the estranged husband and wife.'),
  (115, 107, 1, 'adj', 'based on factors that appear random', 'The boy''s decision to choose one college over another seems arbitrary.'),
  (116, 108, 1, 'n', 'the process or act of resolving a dispute', 'The employee sought official arbitration when he could not resolve a disagreement with his supervisor.'),
  (117, 109, 1, 'adj', 'of or relating to trees', 'Leaves, roots, and bark are a few arboreal traits.'),
  (118, 110, 1, 'adj', 'obscure, secret, known only by a few', 'The professor is an expert in arcane Lithuanian literature.'),
  (119, 111, 1, 'adj', 'of or relating to an earlier period in time, outdated', 'In a few select regions of Western Mongolian, an archaic Chinese dialect is still spoken.'),
  (120, 112, 1, 'adj', 'the most representative or typical example of something', 'Some believe George Washington, with his flowing white hair and commanding stature, was the archetypal politician.'),
  (121, 113, 1, 'n', 'extreme vigor, energy, enthusiasm', 'The soldiers conveyed their ardor with impassioned battle cries.'),
  (122, 114, 1, 'adj', 'excessively dry', 'Little other than palm trees and cacti grow successfully in arid environments.'),
  (123, 115, 1, 'v', 'to take without justification', 'The king arrogated the right to order executions to himself exclusively.'),
  (124, 116, 1, 'n', 'a remaining piece from an extinct culture or place', 'The scientists spent all day searching the cave for artifacts from the ancient Mayan civilization.'),
  (125, 117, 1, 'n', 'a craftsman', 'The artisan uses wood to make walking sticks.'),
  (126, 118, 1, 'v', 'to perceive, learn', 'With a bit of research, the student ascertained that some plants can live for weeks without water.'),
  (127, 119, 1, 'adj', 'practicing restraint as a means of self-discipline, usually religious', 'The priest lives an ascetic life devoid of television, savory foods, and other pleasures.'),
  (128, 120, 1, 'v', 'to assign, credit, attribute to', 'Some ascribe the invention of fireworks and dynamite to the Chinese.'),
  (129, 121, 1, 'n', 'a curse, expression of ill-will', 'The rival politicians repeatedly cast aspersions on each others'' integrity.'),
  (130, 122, 1, 'v', 'to long for, aim toward', 'The young poet aspires to publish a book of verse someday.'),
  (131, 123, 1, 'v', 'to attack', 'At dawn, the war planes assailed the boats in the harbor.'),
  (132, 124, 1, 'v', 'to evaluate', 'A crew arrived to assess the damage after the crash.'),
  (133, 125, 1, 'adj', 'hard-working, diligent', 'The construction workers erected the skyscraper during two years of assiduous labor.'),
  (134, 126, 1, 'v', 'to ease, pacify', 'The mother held the baby to assuage its fears.'),
  (135, 127, 1, 'adj', 'very clever, crafty', 'Much of Roger''s success in politics results from his ability to provide astute answers to reporters'' questions.'),
  (136, 128, 1, 'n', 'a place of refuge, protection, a sanctuary', 'For Thoreau, the forest served as an asylum from the pressures of urban life.'),
